      const req = request.post(`${base}/echo`);
      req.set('MiXeD', 'helloes');
      assert.strictEqual(req.get('mixed'), 'helloes');
    });

    it('should unset header fields case-insensitively', () => {
      const req = request.post(`${base}/echo`);
      req.set('MiXeD', 'helloes');
      req.unset('MIXED');
      assert.strictEqual(req.get('mixed'), undefined);
    });
  });

